@Test func clipboardAdmissionRejectsSensitiveAndPausedContent() {
  #expect(!CapturePolicy.allows(types: ["public.utf8-plain-text"], source: nil, enabled: false))
  #expect(CapturePolicy.allows(types: ["public.utf8-plain-text"], source: nil, enabled: true))
  for type in [
    "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
  ] {
    #expect(!CapturePolicy.allows(types: [type], source: nil, enabled: true))
  }
  #expect(!CapturePolicy.allows(types: [], source: "com.1password.1password", enabled: true))
}

