@Test @MainActor func clipboardPollingUsesOnlyControlledTestPasteboard() throws {
  let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
  defer { try? FileManager.default.removeItem(at: directory) }
  let board = NSPasteboard.withUniqueName()
  defer { board.clearContents() }
  let model = try AppModel(
    directory: directory, pasteboard: board, frontmostApplicationID: { "com.kestrel.test" })
  model.setCapture(true)
  board.clearContents()
  board.setString("Controlled clipboard verification", forType: .string)
  model.checkForClipboardChanges()
  #expect(model.state.history.first?.text == "Controlled clipboard verification")
  model.setCapture(false)
  board.clearContents()
  board.setString("Must not capture", forType: .string)
  model.checkForClipboardChanges()
  #expect(model.state.history.count == 1)
}

