  func findClose(in view: NSView) -> NSButton? {
    if let button = view as? NSButton, button.title == "Close ×" { return button }
    for child in view.subviews { if let found = findClose(in: child) { return found } }
    return nil
  }
  let button = try #require(launcher.panel.contentView.flatMap { findClose(in: $0) })
  launcher.panel.orderFront(nil)
  button.performClick(nil)
  #expect(!launcher.panel.isVisible)
  launcher.panel.orderFront(nil)
  #expect(launcher.panel.isVisible)
  launcher.panel.close()
  #expect(!launcher.panel.isVisible)
}

