@MainActor private func renderedSearchRows(_ launcher: LauncherWindow) -> [(
  labels: [String], icons: [String]
)] {
  func contents(_ view: NSView) -> (labels: [String], icons: [String]) {
    var labels = [String]()
    var icons = [String]()
    if let label = view as? NSTextField { labels.append(label.stringValue) }
    if let image = view as? NSImageView, let name = image.image?.accessibilityDescription {
      icons.append(name)
    }
    for child in view.subviews {
      let nested = contents(child)
      labels += nested.labels
      icons += nested.icons
    }
    return (labels, icons)
  }
  return (0..<launcher.numberOfRows(in: launcher.table)).compactMap { row in
    launcher.tableView(launcher.table, viewFor: launcher.table.tableColumns.first, row: row).map(
      contents)
  }
}

