@Test @MainActor func exactFileMatchSurvivesManyAlphabeticallyEarlierMatches() async throws {
  let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
    .deletingLastPathComponent()
  let token = UUID().uuidString.lowercased()
  let directory = root.appendingPathComponent(
    "Tests/Fixtures/runtime-search-" + token, isDirectory: true)
  try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
  defer { try? FileManager.default.removeItem(at: directory) }
  let name = "kestrel-priority-" + token + ".txt"
  let exact = directory.appendingPathComponent(name)
  try Data("Exact file match".utf8).write(to: exact)
  for index in 0..<40 {
    try Data("Contains match".utf8).write(
      to: directory.appendingPathComponent("000-\(name)-\(index).txt"))
  }
  let importer = Process()
  importer.executableURL = URL(fileURLWithPath: "/usr/bin/mdimport")
  importer.arguments = [directory.path]
  try importer.run()
  importer.waitUntilExit()
  var indexedCount = 0
  for _ in 0..<40 {
    let finder = Process()
    finder.executableURL = URL(fileURLWithPath: "/usr/bin/mdfind")
    finder.arguments = ["-onlyin", directory.path, "kMDItemFSName == '*\(name)*'cd"]
    let output = Pipe()
    finder.standardOutput = output
    try finder.run()
    let data = output.fileHandleForReading.readDataToEndOfFile()
    finder.waitUntilExit()
    indexedCount = String(decoding: data, as: UTF8.self).split(separator: "\n").count
    if indexedCount >= 41 { break }
    try await Task.sleep(for: .milliseconds(200))
  }
  #expect(indexedCount >= 41)
  let search = FileSearch()
  let found: [LaunchCandidate] = await withCheckedContinuation { continuation in
    search.search(name) { continuation.resume(returning: $0) }
  }
  #expect(found.first?.url.path == exact.path)
}

