@Test func accessCheckDistinguishesDeniedFromMissingAndReadable() throws {
  let urls = ["Readable", "Denied", "Missing"].map { URL(fileURLWithPath: "/test/" + $0) }
  let report = SearchAccessReport.inspect(urls) { url in
    if url.lastPathComponent == "Denied" {
      throw NSError(domain: NSCocoaErrorDomain, code: NSFileReadNoPermissionError)
    }
    if url.lastPathComponent == "Missing" {
      throw NSError(domain: NSCocoaErrorDomain, code: NSFileNoSuchFileError)
    }
  }
  #expect(report.entries.map(\.state) == [.readable, .denied, .unavailable])
}

