@MainActor private func settingsButton(_ title: String, in view: NSView) -> NSButton? {
  if let button = view as? NSButton,
    button.title == title || button.accessibilityLabel() == title
  {
    return button
  }
  return view.subviews.lazy.compactMap { settingsButton(title, in: $0) }.first
}

