@Test @MainActor func switchingSettingsSectionsPreservesSnippetDraft() throws {
  let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
  defer { try? FileManager.default.removeItem(at: directory) }
  let settings = SettingsWindow(
    model: try AppModel(directory: directory, pasteboard: .withUniqueName()))
  let content = try #require(settings.window.contentView)
  let snippets = try #require(settingsButton("Snippets", in: content))
  snippets.performClick(nil)
  #expect(settings.titleField.window === settings.window)
  settings.titleField.stringValue = "Draft title"
  settings.bodyField.string = "Unsaved draft body"
  for title in ["General", "Search", "Clipboard"] {
    let button = try #require(settingsButton(title, in: content))
    button.performClick(nil)
    #expect(settings.titleField.window == nil)
    #expect(settings.hasUnsavedChanges)
  }
  snippets.performClick(nil)
  #expect(settings.titleField.stringValue == "Draft title")
  #expect(settings.bodyField.string == "Unsaved draft body")
  #expect(settings.hasUnsavedChanges)
