@Test @MainActor func settingsPagesFitTheMinimumWindowWidth() throws {
  let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
  defer { try? FileManager.default.removeItem(at: directory) }
  let settings = SettingsWindow(
    model: try AppModel(directory: directory, pasteboard: .withUniqueName()))
  settings.window.setContentSize(NSSize(width: 880, height: 600))
  let content = try #require(settings.window.contentView)
  func scrollView(_ view: NSView) -> NSScrollView? {
    if let scroll = view as? NSScrollView { return scroll }
    return view.subviews.lazy.compactMap(scrollView).first
  }
  func controls(_ view: NSView) -> [NSControl] {
    (view as? NSControl).map { [$0] } ?? view.subviews.flatMap(controls)
  }
  for section in ["General", "Appearance", "Search", "Clipboard", "Snippets", "General"] {
    try #require(settingsButton(section, in: content)).performClick(nil)
    content.layoutSubtreeIfNeeded()
    let scroll = try #require(scrollView(content))
    let page = try #require(scroll.documentView)
    #expect(page.frame.width > 500)
    #expect(abs(page.frame.width - scroll.contentView.bounds.width) < 1)
    #expect(page.frame.height > 100)
    if section == "Snippets" { #expect(settings.titleField.frame.width > 300) }
    for control in controls(page) {
      let rect = control.convert(control.bounds, to: page)
      #expect(rect.width > 0)
      #expect(rect.minX >= -1)
      #expect(rect.maxX <= page.bounds.width + 1)
    }
  }
}

