@Test func themeTextContrastAndBackgroundsAreDistinct() {
  func luminance(_ hex: Int) -> Double {
    let channels = [16, 8, 0].map { shift -> Double in
      let value = Double((hex >> shift) & 255) / 255
      return value <= 0.04045 ? value / 12.92 : pow((value + 0.055) / 1.055, 2.4)
    }
    return channels[0] * 0.2126 + channels[1] * 0.7152 + channels[2] * 0.0722
  }
  #expect(Set(KestrelTheme.allCases.map { $0.colors[0] }).count == 5)
  for theme in KestrelTheme.allCases {
    for foreground in [theme.colors[4], theme.colors[5]] {
      for background in [theme.colors[0], theme.colors[1]] {
        let a = luminance(foreground)
        let b = luminance(background)
        #expect((max(a, b) + 0.05) / (min(a, b) + 0.05) >= 4.5)
      }
    }
  }
}

