      try #require(settingsButton(selected, in: content)).performClick(nil)
      for title in ["General", "Appearance", "Search", "Clipboard", "Snippets"] {
        let button = try #require(settingsButton(title, in: content))
        let expected = title == selected ? KestrelBrand.highlight : KestrelBrand.text
        for attributed in [button.attributedTitle, button.attributedAlternateTitle] {
          let actual =
            attributed.length > 0
