@Test @MainActor func nativeThemeButtonsMatchFreshControlsAfterLightThemeSwitch() throws {
  let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
  defer {
    try? FileManager.default.removeItem(at: directory)
    KestrelBrand.setTheme(.nightflight)
  }
  KestrelBrand.setTheme(.nightflight)
  let settings = SettingsWindow(
    model: try AppModel(directory: directory, pasteboard: .withUniqueName()))
  let content = try #require(settings.window.contentView)
  try #require(settingsButton("Appearance", in: content)).performClick(nil)
  for theme in [KestrelTheme.paper, .arctic, .nightflight, .evergreen, .ember] {
    try #require(settingsButton("Use " + theme.title, in: content)).performClick(nil)
    content.layoutSubtreeIfNeeded()
    let button = try #require(
      settingsButton("Use " + (theme == .ember ? "Linen" : "Dusk"), in: content))
    settings.window.effectiveAppearance.performAsCurrentDrawingAppearance {
      if let bitmap = button.bitmapImageRepForCachingDisplay(in: button.bounds) {
        button.cacheDisplay(in: button.bounds, to: bitmap)
      }
      let reference = KestrelActionButton(title: button.title, target: nil, action: nil)
      reference.updateTheme()
      reference.bezelStyle = button.bezelStyle
      reference.appearance = settings.window.appearance
      #expect(button.contentTintColor == reference.contentTintColor)
      #expect(button.bezelColor == reference.bezelColor)
      reference.frame = button.bounds
      func ink(_ view: NSView) -> Int {
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { return 0 }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        var count = 0
        for y in (bitmap.pixelsHigh / 4)..<(bitmap.pixelsHigh * 3 / 4) {
          for x in (bitmap.pixelsWide / 8)..<(bitmap.pixelsWide * 7 / 8) {
            if let c = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.sRGB), c.alphaComponent > 0.5 {
              let light = (c.redComponent + c.greenComponent + c.blueComponent) / 3
              if theme.isDark ? light > 0.7 : light < 0.3 { count += 1 }
            }
          }
        }
        return count
      }
      let actualInk = ink(button)
      let expectedInk = ink(reference)
      #expect(expectedInk > 0)
      #expect(Double(actualInk) >= Double(expectedInk) * 0.8)

    }
  }
}

